 async function batch(files){if(!actions.length){notify('반복할 보정이나 크기 변경을 먼저 기록해주세요.');return;}if(files.length>30){notify('한 번에 최대 30개 이미지를 선택해주세요.');return;}await task(async()=>{validateActions(actions);const output=[];$('batch-progress').hidden=false;try{for(let i=0;i<files.length;i++){let c=await readImage(files[i]);for(const a of actions){if(a.type==='adjust'||a.type==='filter'){const x=ctx(c),im=x.getImageData(0,0,c.width,c.height);im.data.set(a.type==='adjust'?C.adjust(im.data,a.settings):C.filter(im.data,c.width,c.height,a.filter,a.amount));x.putImageData(im,0,0);}else if(a.type==='resize'){const n=make(a.w,a.h);ctx(n).drawImage(c,0,0,a.scale?a.w:c.width,a.scale?a.h:c.height);c=n;}else{const n=make(c.height,c.width),x=ctx(n);x.translate(c.height,0);x.rotate(Math.PI/2);x.drawImage(c,0,0);c=n;}}const b=await blob(c);output.push({name:String(i+1).padStart(2,'0')+'-'+files[i].name.replace(/\.[^.]+$/,'')+'.png',bytes:new Uint8Array(await b.arrayBuffer())});$('batch-progress').value=(i+1)/files.length*100;await new Promise(r=>setTimeout(r,10));}download(new Blob([C.zip(output)],{type:'application/zip'}),'mongle-batch.zip');notify(`${files.length}개 이미지 처리를 완료했습니다.`);}finally{$('batch-progress').hidden=true;}});}
