 $('open-retouch').onclick=()=>{if(!layerActionReady())return;const l=editable();if(!l)return;resetAdjust();const source=layerCanvas(l);MongleRetouch.open({source,mask:selection,opacity:l.opacity,onApply(result,output){if(output==='layer'){if(doc.layers.length>=30)throw Error('새 레이어를 만들려면 레이어를 30개 미만으로 줄여주세요.');const n=fresh('raster',l.name+' · 인물 보정');Object.assign(n,{bitmap:result,opacity:l.opacity,blend:l.blend});add(n);l.visible=false;}else{Object.assign(l,{type:'raster',bitmap:result,maskCanvas:null,x:0,y:0,w:doc.width,h:doc.height,rotation:0,flipX:false,flipY:false,quad:Array(8).fill(0),shadow:{color:'#000000',blur:0,x:0,y:0}});}selection=outline=null;soloId=null;setTool('move');commit('인물 보정');notify('보정을 적용했습니다. Ctrl+Z로 되돌릴 수 있습니다.');}});};
 $('open-refine').onclick=()=>{if(busy||gesture||transforming)return;const l=editable();if(!l)return;if(!selection&&!l.maskCanvas){notify('먼저 영역을 선택하거나 레이어 마스크를 추가해주세요.');return;}resetAdjust();const source=layerCanvas(l,{mask:false}),w=doc.width,h=doc.height;let initial=selection?new Uint8ClampedArray(selection):new Uint8ClampedArray(w*h).fill(255);if(l.maskCanvas){const oldMask=layerCanvas(l,{maskOnly:true,shadow:false}),d=ctx(oldMask).getImageData(0,0,w,h).data;for(let i=0;i<initial.length;i++)initial[i]=initial[i]*d[i*4+3]/255;}MongleRefine.open({source,mask:initial,opacity:l.opacity,onApply(result,output){
  if(output==='layer'&&doc.layers.length>=30)throw Error('새 레이어를 추가하려면 레이어 수를 30개 미만으로 줄여주세요.');
  if(output==='selection'){selection=new Uint8Array(result);selectionOutline();commit('선택 경계 다듬기');return;}
  const m=make(w,h),mx=ctx(m),im=mx.createImageData(w,h);for(let i=0;i<result.length;i++){im.data[i*4]=im.data[i*4+1]=im.data[i*4+2]=255;im.data[i*4+3]=result[i];}mx.putImageData(im,0,0);
  if(output==='mask'){rasterize(l);l.maskCanvas=m;selection=outline=null;commit('경계 다듬은 마스크');return;}
  const cut=copy(source),x=ctx(cut);x.globalCompositeOperation='destination-in';x.drawImage(m,0,0);const d=x.getImageData(0,0,w,h).data,a=new Uint8Array(w*h);for(let i=0;i<a.length;i++)a[i]=d[i*4+3];const b=C.bounds(a,w,h);if(!b)throw Error('남은 영역이 없습니다. 브러시로 복원하거나 보정값을 줄여주세요.');const bitmap=make(b.w,b.h);ctx(bitmap).drawImage(cut,b.x,b.y,b.w,b.h,0,0,b.w,b.h);const n=fresh('raster',l.name+' · 경계 보정',b.w,b.h);Object.assign(n,{x:b.x,y:b.y,bitmap,opacity:l.opacity,blend:l.blend});add(n);l.visible=false;selection=outline=null;setTool('move');commit('경계 보정 새 레이어');notify('새 레이어를 만들고 원본을 숨겼습니다. Ctrl+T로 배치하세요.');
 }});};
